// budget-tracker.cjs — PostToolUse handler: estimate token cost from each tool call.
// PostToolUse stdin provides `tool_input` (generated by the model) and `tool_response`
// (read back into its context).
// Live per-Bash cost tracker (runs in all hook profiles).
//
// Estimation: chars / 4 ≈ tokens (rough, English text). Imprecise but order-of-magnitude.
// Pricing: per 1M tokens (input/output) by model tier.
//
// User-facing only: both notices are plain stdout, which the host keeps in the transcript and
// does not show to the model. That is deliberate: a spend figure in the model's context
// changes how much it spends, and a cost estimate is the user's call. Nothing is stopped. The
// estimate resets with each new session (project-context-loader clears the state file).
//
// Thresholds come from the project config, which is committed and therefore the
// same for everyone on the team:
//   budget.warn   first-warning threshold in USD (default: 30)
//   budget.block  over-budget notice threshold in USD (default: 100)
//   budget.cap    overrides budget.block, lower OR higher

const { resolveConfig } = require('../lib/read-config.cjs');

// Pricing per 1M tokens [input, output] in USD
const PRICING = {
  COMPLEX: { input: 15, output: 75 },
  STANDARD: { input: 3, output: 15 },
  TRIVIAL: { input: 0.80, output: 4 },
};

function estimateTokens(text) {
  if (!text) return 0;
  const str = typeof text === 'string' ? text : JSON.stringify(text);
  return Math.ceil(str.length / 4);
}

module.exports = function budgetTracker(ctx, state) {
  // The tool's result is read back into the model's context, so it is billed at the
  // input rate; the tool call's arguments are text the model generated, billed at the
  // output rate. Pricing the result as output overstated cost about fivefold.
  const inputTokens = estimateTokens(ctx.tool_response);
  const outputTokens = estimateTokens(ctx.tool_input);
  if (inputTokens === 0 && outputTokens === 0) return '';

  // Load model tier from detected-model (written by model-detector at SessionStart)
  const modelInfo = state.load('detected-model');
  const tier = modelInfo?.tier || 'STANDARD';
  const pricing = PRICING[tier] || PRICING.STANDARD;

  // Load or initialize budget state
  const budget = state.load('budget-state') || {
    session_start: new Date().toISOString(),
    model_tier: tier,
    estimated_input_tokens: 0,
    estimated_output_tokens: 0,
    estimated_cost_usd: 0,
    turn_count: 0,
    warnings_emitted: 0,
  };

  // Accumulate
  budget.estimated_input_tokens += inputTokens;
  budget.estimated_output_tokens += outputTokens;
  budget.turn_count += 1;
  budget.model_tier = tier;

  // Calculate cost
  const inputCost = (budget.estimated_input_tokens / 1_000_000) * pricing.input;
  const outputCost = (budget.estimated_output_tokens / 1_000_000) * pricing.output;
  budget.estimated_cost_usd = Math.round((inputCost + outputCost) * 100) / 100;

  state.save('budget-state', budget);

  // Check thresholds (explicit undefined check to allow 0 as valid value)
  const { values } = resolveConfig({ root: ctx.root });
  const warnThreshold = values['budget.warn'] !== undefined ? Number(values['budget.warn']) : 30;
  // `budget.cap` overrides the hard block when it is set.
  const blockThreshold = values['budget.cap'] !== undefined
    ? Number(values['budget.cap'])
    : (values['budget.block'] !== undefined ? Number(values['budget.block']) : 100);

  if (budget.estimated_cost_usd >= blockThreshold) {
    budget.warnings_emitted += 1;
    state.save('budget-state', budget);
    return `@@BUDGET_OVER@@\nEstimated cost: $${budget.estimated_cost_usd} (cap: $${blockThreshold}). Session estimate is over the cap. Advisory: nothing is stopped.\nDetails: .meowkit/state/budget-state.json.\n@@END_BUDGET@@\n`;
  }

  if (budget.estimated_cost_usd >= warnThreshold && budget.warnings_emitted === 0) {
    budget.warnings_emitted += 1;
    state.save('budget-state', budget);
    return `@@BUDGET_WARN@@\nEstimated cost: $${budget.estimated_cost_usd} (warn at $${warnThreshold}, cap at $${blockThreshold}). Advisory.\n@@END_BUDGET@@\n`;
  }

  return '';
};
